\href{https://stacks.math.columbia.edu/tag/0CKY}{\texttt{Stacks tag 0CKY}}


\begin{reference}
Lemma in an email of Matthew Emerton dated June 15, 2016
\end{reference}
Let $S$ be a scheme contained in $\Sch_{fppf}$.
Let $\mathcal{X} \to \mathcal{Z}$ and $\mathcal{Y} \to \mathcal{Z}$
be $1$-morphisms of categories fibred in groupoids over $(\Sch/S)_{fppf}$.
If $\mathcal{X} \to \mathcal{Z}$ is representable by algebraic spaces
and $\mathcal{Y}$ is a stack in groupoids, then
$\mathcal{X} \times_\mathcal{Z} \mathcal{Y}$ is a stack in groupoids.

\href{https://stacks.math.columbia.edu/tag/04SZ}{\texttt{Stacks tag 04SZ}}


Let $S$ be a scheme contained in $\Sch_{fppf}$.
Let $\mathcal{X}$ be an algebraic stack over $S$.
The following are equivalent
\begin{enumerate}
\item $\mathcal{X}$ is a stack in setoids,
\item the canonical $1$-morphism $\mathcal{I}_\mathcal{X} \to \mathcal{X}$
is an equivalence, and
\item $\mathcal{X}$ is representable by an algebraic space.
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/04Y5}{\texttt{Stacks tag 04Y5}}


Let $S$ be a scheme contained in $\Sch_{fppf}$.
Let $f : \mathcal{X} \to \mathcal{Y}$ be a $1$-morphism of algebraic
stacks over $S$. The following are equivalent:
\begin{enumerate}
\item for $U \in \Ob((\Sch/S)_{fppf})$
the functor $f : \mathcal{X}_U \to \mathcal{Y}_U$ is faithful,
\item the functor $f$ is faithful, and
\item $f$ is representable by algebraic spaces.
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/05UL}{\texttt{Stacks tag 05UL}}


Let $S$ be a scheme contained in $\Sch_{fppf}$.
Let $u : \mathcal{U} \to \mathcal{X}$ be a $1$-morphism of
stacks in groupoids over $(\Sch/S)_{fppf}$. If
\begin{enumerate}
\item $\mathcal{U}$ is representable by an algebraic space, and
\item $u$ is representable by algebraic spaces, surjective and smooth,
\end{enumerate}
then $\mathcal X$ is an algebraic stack over $S$.

\href{https://stacks.math.columbia.edu/tag/05UM}{\texttt{Stacks tag 05UM}}


Let $S$ be a scheme contained in $\Sch_{fppf}$.
Let $\mathcal{X} \to \mathcal{Y}$ be a morphism of stacks in groupoids
over $(\Sch/S)_{fppf}$. Assume that
\begin{enumerate}
\item $\mathcal{X} \to \mathcal{Y}$ is representable by algebraic spaces, and
\item $\mathcal{Y}$ is an algebraic stack over $S$.
\end{enumerate}
Then $\mathcal{X}$ is an algebraic stack over $S$.

\href{https://stacks.math.columbia.edu/tag/04X5}{\texttt{Stacks tag 04X5}}


Let $\Sch_{fppf}$ be a big fppf site.
Let $S \to S'$ be a morphism of this site.
The constructions A and B of
Stacks, Section \ref{stacks-section-localize}
above give isomorphisms of $2$-categories
$$
\left\{
\begin{matrix}
2\text{-category of algebraic}\\
\text{stacks }\mathcal{X}\text{ over }S
\end{matrix}
\right\}
\leftrightarrow
\left\{
\begin{matrix}
2\text{-category of pairs }(\mathcal{X}', f)\text{ consisting of an}\\
\text{algebraic stack }\mathcal{X}'\text{ over }S'\text{ and a morphism}\\
f : \mathcal{X}' \to (\Sch/S)_{fppf}\text{ of algebraic stacks over }S'
\end{matrix}
\right\}
$$

\href{https://stacks.math.columbia.edu/tag/04X6}{\texttt{Stacks tag 04X6}}



Let $\Sch_{fppf}$ be a big fppf site.
Let $S \to S'$ be a morphism of this site.
If $p : \mathcal{X} \to (\Sch/S)_{fppf}$
is an algebraic stack over $S$, then
$\mathcal{X}$ {\it viewed as an algebraic stack over $S'$}
is the algebraic stack
$$
\mathcal{X} \longrightarrow (\Sch/S')_{fppf}
$$
gotten by applying construction A of
Lemma \ref{algebraic-lemma-category-of-spaces-over-smaller-base-scheme}
to $\mathcal{X}$.

\href{https://stacks.math.columbia.edu/tag/07T5}{\texttt{Stacks tag 07T5}}


The functor $p : \mathcal{F} \to \mathcal{C}_\Lambda$ defined above
is a predeformation category.

\href{https://stacks.math.columbia.edu/tag/07WP}{\texttt{Stacks tag 07WP}}


Let $S$ be a locally Noetherian scheme. Let $\mathcal{Z}$ be a category
fibred in groupoids over $(\Sch/S)_{fppf}$. We say $\mathcal{Z}$
satisfies {\it condition (RS)} if for every pushout
$$
\begin{array}{cc}X \longrightarrow\downarrow & X' \downarrow \\ Y \longrightarrow & Y' = Y \amalg_X X'\end{array}
$$
in the category of schemes over $S$ where
\begin{enumerate}
\item $X$, $X'$, $Y$, $Y'$ are spectra of local Artinian rings,
\item $X$, $X'$, $Y$, $Y'$ are of finite type over $S$, and
\item $X \to X'$ (and hence $Y \to Y'$) is a closed immersion
\end{enumerate}
the functor of fibre categories
$$
\mathcal{Z}_{Y'}
\longrightarrow
\mathcal{Z}_Y \times_{\mathcal{Z}_X} \mathcal{Z}_{X'}
$$
is an equivalence of categories.

\href{https://stacks.math.columbia.edu/tag/07WQ}{\texttt{Stacks tag 07WQ}}


Let $\mathcal{X}$ be an algebraic stack over a locally Noetherian base
$S$. Then $\mathcal{X}$ satisfies (RS).

\href{https://stacks.math.columbia.edu/tag/07X1}{\texttt{Stacks tag 07X1}}


Let $S$ be a locally Noetherian scheme. Assume
\begin{enumerate}
\item $\mathcal{X}$ is an algebraic stack,
\item $U$ is a scheme locally of finite type over $S$, and
\item $(\Sch/U)_{fppf} \to \mathcal{X}$ is a smooth surjective
morphism.
\end{enumerate}
Then, for any $\mathcal{F} = \mathcal{F}_{\mathcal{X}, k, x_0}$ as in
Section \ref{artin-section-predeformation-categories}
the tangent space $T\mathcal{F}$ and infinitesimal automorphism space
$\text{Inf}(\mathcal{F})$ have finite dimension over $k$.

\href{https://stacks.math.columbia.edu/tag/07X7}{\texttt{Stacks tag 07X7}}


Let $S$ be a locally Noetherian scheme. Let $\mathcal{X}$ be a category
fibred in groupoids over $(\Sch/S)_{fppf}$. A formal object
$\xi = (R, \xi_n, f_n)$ of $\mathcal{X}$ is called {\it effective}
if it is in the essential image of the functor
(\ref{equation-approximation}).

\href{https://stacks.math.columbia.edu/tag/07X8}{\texttt{Stacks tag 07X8}}


Let $S$ be a locally Noetherian scheme. Let $\mathcal{X}$ be an algebraic
stack over $S$. The functor (\ref{equation-approximation}) is an equivalence.

\href{https://stacks.math.columbia.edu/tag/07XN}{\texttt{Stacks tag 07XN}}


Let $S$ be a scheme. Let $\mathcal{X}$ be an algebraic stack over $S$.
Then the following are equivalent
\begin{enumerate}
\item $\mathcal{X}$ is a stack in setoids and
$\mathcal{X} \to (\Sch/S)_{fppf}$ is limit preserving on objects,
\item $\mathcal{X}$ is a stack in setoids and limit preserving,
\item $\mathcal{X}$ is representable by an algebraic space
locally of finite presentation.
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/0CXL}{\texttt{Stacks tag 0CXL}}


Let $S$ be a locally Noetherian scheme. Let $f : U \to V$
be a morphism of schemes locally of finite type over $S$.
Let $u_0 \in U$ be a finite type point. The following are equivalent
\begin{enumerate}
\item $f$ is smooth at $u_0$,
\item $f$ viewed as an object of $(\Sch/V)_{fppf}$ over $U$ is
versal at $u_0$.
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/07Y1}{\texttt{Stacks tag 07Y1}}


Let $S$ be a locally Noetherian scheme. Let
$F : (\Sch/S)_{fppf}^{opp} \to \textit{Sets}$ be a functor. Assume that
\begin{enumerate}
\item $\Delta : F \to F \times F$ is representable by algebraic spaces,
\item $F$ satisfies axioms [-1], [0], [1], [2], [3], [4], [5]
(see Section \ref{artin-section-axioms-functors}), and
\item $\mathcal{O}_{S, s}$ is a G-ring for all finite type points $s$ of $S$.
\end{enumerate}
Then $F$ is an algebraic space.

\href{https://stacks.math.columbia.edu/tag/0CXP}{\texttt{Stacks tag 0CXP}}


Let $\mathcal{X}$ be an algebraic stack over a base $S$.
Then $\mathcal{X}$ satisfies (RS*).

\href{https://stacks.math.columbia.edu/tag/0CXU}{\texttt{Stacks tag 0CXU}}



Let $S$ be a locally Noetherian scheme. Let $\mathcal{X}$ be a category fibred
in groupoids over $(\Sch/S)_{fppf}$. Assume
\begin{enumerate}
\item $\Delta : \mathcal{X} \to \mathcal{X} \times \mathcal{X}$ is
representable by algebraic spaces,
\item $\mathcal{X}$ has (RS*),
\item $\mathcal{X}$ is limit preserving,
\item systems $(\xi_n)$ as in Remark \ref{artin-remark-strong-effectiveness}
where $\Ker(R_m \to R_n)$ is an ideal of square zero for all $m \geq n$
are effective.
\end{enumerate}
Then $\mathcal{X}$ satisfies openness of versality.

\href{https://stacks.math.columbia.edu/tag/0CYF}{\texttt{Stacks tag 0CYF}}



\begin{reference}
This is \cite[Theorem 4.4]{Hall-coherent}
\end{reference}
Let $S$ be a locally Noetherian scheme. Let $\mathcal{X}$ be a category fibred
in groupoids over $(\Sch/S)_{fppf}$. Assume
\begin{enumerate}
\item $\Delta : \mathcal{X} \to \mathcal{X} \times \mathcal{X}$ is
representable by algebraic spaces,
\item $\mathcal{X}$ has (RS*),
\item $\mathcal{X}$ is limit preserving,
\item there exists an obstruction theory\footnote{Analyzing the proof
the reader sees that in fact it suffices to check
the functoriality (ii) of obstruction classes in
Definition \ref{artin-definition-obstruction-theory}
for maps $(y, B' \to B) \to (x, A' \to A)$
with $B = A$ and $y = x$.},
\item for an object $x$ of $\mathcal{X}$ over $\Spec(A)$
and $A$-modules $M_n$, $n \geq 1$ we have
\begin{enumerate}
\item $T_x(\prod M_n) = \prod T_x(M_n)$,
\item $\mathcal{O}_x(\prod M_n) \to \prod \mathcal{O}_x(M_n)$
is injective.
\end{enumerate}
\end{enumerate}
Then $\mathcal{X}$ satisfies openness of versality.

\href{https://stacks.math.columbia.edu/tag/07YK}{\texttt{Stacks tag 07YK}}


Let $A \to k$ be a ring map with $k$ a field. Let $E \in D^-(A)$.
Then $\Ext^i_A(E, k) = \Hom_k(H^{-i}(E \otimes^\mathbf{L} k), k)$.

\href{https://stacks.math.columbia.edu/tag/0GHE}{\texttt{Stacks tag 0GHE}}



In Situation \ref{artin-situation-contractions} assume given a closed
subset $Z \subset S$ such that
\begin{enumerate}
\item the inverse image of $Z$ in $X'$ is $T'$,
\item $U' \to S \setminus Z$ is a closed immersion,
\item $W \to S_{/Z}$ is a closed immersion.
\end{enumerate}
Then there exists a solution $(f : X' \to X, T, a)$
and moreover $X \to S$ is a closed immersion.

\href{https://stacks.math.columbia.edu/tag/0GI6}{\texttt{Stacks tag 0GI6}}



In Situation \ref{artin-situation-contractions} the functor $F$ satisfies
the Rim-Schlessinger condition (RS).

\href{https://stacks.math.columbia.edu/tag/0GI7}{\texttt{Stacks tag 0GI7}}



In Situation \ref{artin-situation-contractions} the tangent spaces of
the functor $F$ are finite dimensional.

\href{https://stacks.math.columbia.edu/tag/0GI8}{\texttt{Stacks tag 0GI8}}



In Situation \ref{artin-situation-contractions} assume $X' \to S$ is separated.
Then every formal object for $F$ is effective.

\href{https://stacks.math.columbia.edu/tag/0GIA}{\texttt{Stacks tag 0GIA}}



In Situation \ref{artin-situation-contractions} the functor
$F$ satisfies openness of versality.

\href{https://stacks.math.columbia.edu/tag/0762}{\texttt{Stacks tag 0762}}


Let $\mathcal{X}$ be an algebraic stack and let $\mathcal{F}$ in
$\textit{Mod}(\mathcal{X}_\etale, \mathcal{O}_\mathcal{X})$.
We say $\mathcal{F}$ has the {\it flat base change property}\footnote{This
may be nonstandard notation.}
if and only if $c_\varphi$ is an isomorphism whenever $f$ is flat.

\href{https://stacks.math.columbia.edu/tag/0GR0}{\texttt{Stacks tag 0GR0}}


Let $\mathcal{X}$ be an algebraic stack. Notation as in
Lemma \ref{stacks-cohomology-lemma-lisse-etale}.
\begin{enumerate}
\item For an abelian sheaf $\mathcal{F}$ on $\mathcal{X}_\etale$ we have
\begin{enumerate}
\item $H^p(\mathcal{X}_\etale, \mathcal{F}) =
H^p(\mathcal{X}_{lisse,\etale}, g^{-1}\mathcal{F})$, and
\item $H^p(x, \mathcal{F}) =
H^p(\mathcal{X}_{lisse,\etale}/x, g^{-1}\mathcal{F})$
for any object $x$ of $\mathcal{X}_{lisse,\etale}$.
\end{enumerate}
The same holds for sheaves of modules.
\item For an abelian sheaf $\mathcal{F}$ on $\mathcal{X}_{fppf}$ we have
\begin{enumerate}
\item $H^p(\mathcal{X}_{fppf}, \mathcal{F}) =
H^p(\mathcal{X}_{flat,fppf}, g^{-1}\mathcal{F})$, and
\item $H^p(x, \mathcal{F}) =
H^p(\mathcal{X}_{flat,fppf}/x, g^{-1}\mathcal{F})$
for any object $x$ of $\mathcal{X}_{flat,fppf}$.
\end{enumerate}
The same holds for sheaves of modules.
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/078A}{\texttt{Stacks tag 078A}}


Let $\mathcal{X}$ be an algebraic stack. Notation as in
Lemmas \ref{stacks-cohomology-lemma-lisse-etale} and \ref{stacks-cohomology-lemma-lisse-etale-modules}.
\begin{enumerate}
\item We have $g_!\mathcal{O}_{\mathcal{X}_{lisse,\etale}} =
\mathcal{O}_\mathcal{X}$.
\item We have $g_!\mathcal{O}_{\mathcal{X}_{flat, fppf}} =
\mathcal{O}_\mathcal{X}$.
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/07AR}{\texttt{Stacks tag 07AR}}


Let $\mathcal{X}$ be an algebraic stack.
\begin{enumerate}
\item Let $\mathcal{F}$ be an $\mathcal{O}_\mathcal{X}$-module
with the flat base change property on $\mathcal{X}_\etale$.
The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is parasitic, and
\item $g^*\mathcal{F} = 0$ where
$g : \Sh(\mathcal{X}_{lisse,\etale}) \to
\Sh(\mathcal{X}_\etale)$ is as in Lemma \ref{stacks-cohomology-lemma-lisse-etale}.
\end{enumerate}
\item Let $\mathcal{F}$ be an $\mathcal{O}_\mathcal{X}$-module on
$\mathcal{X}_{fppf}$. The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is parasitic, and
\item $g^*\mathcal{F} = 0$ where
$g :  \Sh(\mathcal{X}_{flat,fppf}) \to \Sh(\mathcal{X}_{fppf})$
is as in Lemma \ref{stacks-cohomology-lemma-lisse-etale}.
\end{enumerate}
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/0GR3}{\texttt{Stacks tag 0GR3}}


With assumptions and notation as in Lemma \ref{stacks-cohomology-lemma-lisse-etale-functorial}
the canonical (base change) map
$$
g^{-1}Rf_*\mathcal{F} \longrightarrow Rf'_*(g')^{-1}\mathcal{F}
$$
is an isomorphism for any abelian sheaf $\mathcal{F}$
on $\mathcal{X}_\etale$ (resp.\ $\mathcal{X}_{fppf}$).

\href{https://stacks.math.columbia.edu/tag/07B1}{\texttt{Stacks tag 07B1}}


Let $\mathcal{X}$ be an algebraic stack.
\begin{enumerate}
\item With $g$ as in Lemma \ref{stacks-cohomology-lemma-lisse-etale}
for the lisse-\'etale site we have
\begin{enumerate}
\item the functors $g^{-1}$ and $g_!$ define mutually inverse functors
$$
\begin{array}{cc}\QCoh(\mathcal{O}_\mathcal{X}) \overset{g^{-1}}{\longrightarrow} & \QCoh(\mathcal{X}_{lisse,\etale},
\mathcal{O}_{\mathcal{X}_{lisse,\etale}}) \overset{g_!}{\longleftarrow}\end{array}
$$
\item if $\mathcal{F}$ is in $\textit{LQCoh}^{fbc}(\mathcal{O}_\mathcal{X})$
then $g^{-1}\mathcal{F}$ is in
$\QCoh(\mathcal{O}_{\mathcal{X}_{lisse,\etale}})$ and
\item $Q(\mathcal{F}) = g_!g^{-1}\mathcal{F}$ where $Q$ is as in
Lemma \ref{stacks-cohomology-lemma-adjoint}.
\end{enumerate}
\item With $g$ as in Lemma \ref{stacks-cohomology-lemma-lisse-etale}
for the flat-fppf site we have
\begin{enumerate}
\item the functors $g^{-1}$ and $g_!$ define mutually inverse functors
$$
\begin{array}{cc}\QCoh(\mathcal{O}_\mathcal{X}) \overset{g^{-1}}{\longrightarrow} & \QCoh(\mathcal{X}_{flat,fppf},
\mathcal{O}_{\mathcal{X}_{flat,fppf}}) \overset{g_!}{\longleftarrow}\end{array}
$$
\item if $\mathcal{F}$ is in $\textit{LQCoh}^{fbc}(\mathcal{O}_\mathcal{X})$
then $g^{-1}\mathcal{F}$ is in
$\QCoh(\mathcal{O}_{\mathcal{X}_{flat,fppf}})$
and
\item $Q(\mathcal{F}) = g_!g^{-1}\mathcal{F}$ where $Q$ is as in
Lemma \ref{stacks-cohomology-lemma-adjoint}.
\end{enumerate}
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/07B4}{\texttt{Stacks tag 07B4}}


Let $\mathcal{X}$ be an algebraic stack.
\begin{enumerate}
\item $\QCoh(\mathcal{O}_{\mathcal{X}_{lisse,\etale}})$
is a weak Serre subcategory of
$\textit{Mod}(\mathcal{O}_{\mathcal{X}_{lisse,\etale}})$.
\item $\QCoh(\mathcal{O}_{\mathcal{X}_{flat,fppf}})$
is a weak Serre subcategory of
$\textit{Mod}(\mathcal{O}_{\mathcal{X}_{flat,fppf}})$.
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/0GRD}{\texttt{Stacks tag 0GRD}}


Let $\mathcal{X}$ be a locally Noetherian algebraic stack. Let $\mathcal{F}$
and $\mathcal{G}$ be coherent be $\mathcal{O}_\mathcal{X}$-modules. Then
the internal hom $hom(\mathcal{F}, \mathcal{G})$
constructed in Lemma \ref{stacks-cohomology-lemma-internal-hom-fp-into-qcoh}
is a coherent $\mathcal{O}_\mathcal{X}$-module.

\href{https://stacks.math.columbia.edu/tag/06CX}{\texttt{Stacks tag 06CX}}


Let $p : \mathcal{X} \to \mathcal{Y}$ be a $1$-morphism of categories
fibred in groupoids over $(\Sch/S)_{fppf}$. If $p$ is
representable by algebraic spaces, then the following are equivalent:
\begin{enumerate}
\item $p$ is limit preserving on objects, and
\item $p$ is locally of finite presentation (see
Algebraic Stacks,
Definition \ref{algebraic-definition-relative-representable-property}).
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/06D3}{\texttt{Stacks tag 06D3}}


Let $p : \mathcal{X} \to \mathcal{Y}$ be a $1$-morphism of categories
fibred in groupoids over $(\Sch/S)_{fppf}$. If $p$ is
representable by algebraic spaces, then the following are equivalent:
\begin{enumerate}
\item $p$ is formally smooth on objects, and
\item $p$ is formally smooth (see
Algebraic Stacks,
Definition \ref{algebraic-definition-relative-representable-property}).
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/06D7}{\texttt{Stacks tag 06D7}}


Let $p : \mathcal{X} \to \mathcal{Y}$ be a $1$-morphism of categories
fibred in groupoids over $(\Sch/S)_{fppf}$. If $p$ is
representable by algebraic spaces, then the following are equivalent:
\begin{enumerate}
\item $p$ is surjective on objects, and
\item $p$ is surjective (see
Algebraic Stacks,
Definition \ref{algebraic-definition-relative-representable-property}).
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/05XY}{\texttt{Stacks tag 05XY}}


Let $S$ be a scheme.
Let $F : \mathcal{X} \to \mathcal{Y}$ be a $1$-morphism of
stacks in groupoids over $(\Sch/S)_{fppf}$. If
\begin{enumerate}
\item $\mathcal{Y}$ is an algebraic stack, and
\item $F$ is algebraic (see above),
\end{enumerate}
then $\mathcal{X}$ is an algebraic stack.

\href{https://stacks.math.columbia.edu/tag/05Y5}{\texttt{Stacks tag 05Y5}}


Let $S$ be a scheme. Let $Z \to B$ and $X' \to X \to B$ be morphisms of
algebraic spaces over $S$. Assume
\begin{enumerate}
\item $X' \to X$ is \'etale, and
\item $Z \to B$ is finite locally free.
\end{enumerate}
Then $\mathit{Mor}_B(Z, X') \to \mathit{Mor}_B(Z, X)$ is representable
by algebraic spaces and \'etale. If $X' \to X$ is also surjective,
then $\mathit{Mor}_B(Z, X') \to \mathit{Mor}_B(Z, X)$ is surjective.

\href{https://stacks.math.columbia.edu/tag/05YD}{\texttt{Stacks tag 05YD}}


Let $S$ be a scheme. Let $X' \to X \to Z \to B$ be morphisms of
algebraic spaces over $S$. Assume
\begin{enumerate}
\item $X' \to X$ is \'etale, and
\item $Z \to B$ is finite locally free.
\end{enumerate}
Then $\text{Res}_{Z/B}(X') \to \text{Res}_{Z/B}(X)$ is representable
by algebraic spaces and \'etale. If $X' \to X$ is also surjective,
then $\text{Res}_{Z/B}(X') \to \text{Res}_{Z/B}(X)$ is surjective.

\href{https://stacks.math.columbia.edu/tag/05XP}{\texttt{Stacks tag 05XP}}



In the situation of
Lemma \ref{criteria-lemma-map-hilbert}
assume that the given square is $2$-cartesian. Then the diagram
$$
\begin{array}{cc}\mathcal{H}_d(\mathcal{X}'/\mathcal{Y}') \longrightarrow\downarrow & \mathcal{H}_d(\mathcal{X}/\mathcal{Y}) \downarrow \\ \mathcal{Y}' \longrightarrow & \mathcal{Y}\end{array}
$$
is $2$-cartesian.

\href{https://stacks.math.columbia.edu/tag/06CI}{\texttt{Stacks tag 06CI}}


Let $S$ be a scheme. Let $F : \mathcal{X} \to \mathcal{Y}$ be a $1$-morphism
of stacks in groupoids over $(\Sch/S)_{fppf}$ such that
\begin{enumerate}
\item $\mathcal{X}$ is representable by an algebraic space, and
\item $F$ is representable by algebraic spaces, surjective, flat, and
locally of finite presentation.
\end{enumerate}
Then $\mathcal{H}_d(\mathcal{X}/\mathcal{Y})$ is an algebraic stack.

\href{https://stacks.math.columbia.edu/tag/06DC}{\texttt{Stacks tag 06DC}}



Let $S$ be a scheme. Let $F : \mathcal{X} \to \mathcal{Y}$
be a $1$-morphism of stacks in groupoids over $(\Sch/S)_{fppf}$. If
\begin{enumerate}
\item $\mathcal{X}$ is representable by an algebraic space, and
\item $F$ is representable by algebraic spaces, surjective, flat and
locally of finite presentation,
\end{enumerate}
then $\mathcal{Y}$ is an algebraic stack.

\href{https://stacks.math.columbia.edu/tag/0H16}{\texttt{Stacks tag 0H16}}


Let $\mathcal{X}$ be an algebraic stack. Then $\mathit{QC}(\mathcal{X})$
is canonically equivalent to $D_\QCoh(\mathcal{O}_\mathcal{X})$.

\href{https://stacks.math.columbia.edu/tag/04U5}{\texttt{Stacks tag 04U5}}


Let $(X, \mathcal{O}_X)$ be a ringed space.
\begin{enumerate}
\item The category of finite type $\mathcal{O}_X$-modules has a
set of isomorphism classes.
\item The category of finite type quasi-coherent
$\mathcal{O}_X$-modules has a set of isomorphism classes.
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/0BLZ}{\texttt{Stacks tag 0BLZ}}


The functor
$$
p : \textit{F\'Et} \longrightarrow (\Sch/S)_{fppf}
$$
defines a stack over $(\Sch/S)_{fppf}$.

\href{https://stacks.math.columbia.edu/tag/04UK}{\texttt{Stacks tag 04UK}}


Up to a replacement as in
Stacks, Remark \ref{stacks-remark-stack-make-small}
the functor
$$
p : \mathcal{G}\textit{-Torsors} \longrightarrow (\Sch/S)_{fppf}
$$
defines a stack in groupoids over $(\Sch/S)_{fppf}$.

\href{https://stacks.math.columbia.edu/tag/04UM}{\texttt{Stacks tag 04UM}}


Up to a replacement as in
Stacks, Remark \ref{stacks-remark-stack-make-small}
the functor
$$
p :
\mathcal{G}/\mathcal{B}\textit{-Torsors}
\longrightarrow
(\Sch/S)_{fppf}
$$
defines a stack in groupoids over $(\Sch/S)_{fppf}$.

\href{https://stacks.math.columbia.edu/tag/04US}{\texttt{Stacks tag 04US}}


Up to a replacement as in
Stacks, Remark \ref{stacks-remark-stack-make-small}
the functor
$$
p : G\textit{-Torsors} \longrightarrow (\Sch/S)_{fppf}
$$
defines a stack in groupoids over $(\Sch/S)_{fppf}$.

